from datetime import datetime, timedelta, timezone


class Transient(Exception):
    pass


_STATES = {"paid": "open", "refunded": "void"}
_CURRENCIES = {"EUR", "USD", "GBP"}


def _money(cents):
    if not isinstance(cents, int) or isinstance(cents, bool) or cents < 0:
        raise ValueError(f"bad amount: {cents!r}")
    return f"{cents // 100}.{cents % 100:02d}"


def order_to_invoice(order, offset_minutes):
    created = datetime.fromisoformat(order["created_at"])
    if created.tzinfo is None:
        raise ValueError("created_at has no time zone")
    local = created.astimezone(timezone(timedelta(minutes=offset_minutes)))
    customer = order.get("customer") or {}
    name = " ".join(p for p in ((customer.get(k) or "").strip() for k in ("first_name", "last_name")) if p)
    if not name:
        raise ValueError("customer name missing")
    email = (customer.get("email") or "").strip().lower()
    local_part, at, domain = email.partition("@")
    if not at or not local_part or not domain or "@" in domain:
        raise ValueError("bad email")
    currency = order.get("currency")
    if currency not in _CURRENCIES:
        raise ValueError(f"unsupported currency: {currency}")
    status = order.get("status")
    if status not in _STATES:
        raise ValueError(f"unmapped status: {status}")
    total = order.get("total_cents")
    amount = _money(total)
    lines, line_total = [], 0
    for line in order.get("lines", []):
        qty = line.get("qty")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            raise ValueError(f"bad quantity: {qty!r}")
        lines.append({"code": line.get("sku"), "quantity": qty, "unit_price": _money(line.get("unit_cents"))})
        line_total += qty * line["unit_cents"]
    if line_total != total:
        raise ValueError("total does not match lines")
    return {"external_ref": f"shop-{order['id']}", "date": local.date().isoformat(), "customer_name": name, "email": email,
            "currency": currency, "amount": amount, "state": _STATES[status], "lines": lines}


class OrderSync:
    def __init__(self, shop, books, offset_minutes, state=None):
        self.shop = shop
        self.books = books
        self.offset = offset_minutes
        self.state = state if state is not None else {"since": None, "seen": [], "links": {}, "dead": []}

    def _books(self, call, *args):
        for attempt in range(1, 4):
            try:
                return call(*args)
            except Transient as e:
                if attempt == 3:
                    raise ValueError(str(e))

    def _set_dead(self, order_id, reason):
        self.state["dead"] = [d for d in self.state["dead"] if d["order"] != order_id]
        if reason is not None:
            self.state["dead"].append({"order": order_id, "reason": reason})

    def _handle(self, order, summary):
        order_id = order["id"]
        links = self.state["links"]
        if order.get("deleted"):
            if order_id in links:
                self._books(self.books.void_invoice, links[order_id])
                summary["voided"] += 1
            return
        try:
            invoice = order_to_invoice(order, self.offset)
        except (ValueError, KeyError, TypeError) as e:
            raise _Dead(f"mapping: {e}")
        if order_id in links:
            self._books(self.books.update_invoice, links[order_id], invoice)
            summary["updated"] += 1
        else:
            links[order_id] = self._books(self.books.create_invoice, invoice)
            summary["created"] += 1

    def run(self):
        since, seen = self.state["since"], set(self.state["seen"])
        orders = self.shop.changed_orders(since)
        summary = {"created": 0, "updated": 0, "voided": 0, "dead": 0, "since": since}
        for order in orders:
            if since is not None and order["updated_at"] == since and order["id"] in seen:
                continue
            try:
                self._handle(order, summary)
                self._set_dead(order["id"], None)
            except _Dead as e:
                self._set_dead(order["id"], str(e))
                summary["dead"] += 1
            except ValueError as e:
                self._set_dead(order["id"], f"books: {e}")
                summary["dead"] += 1
        if orders:
            top = max(o["updated_at"] for o in orders)
            if since is None or top > since:
                since, seen = top, set()
            seen |= {o["id"] for o in orders if o["updated_at"] == since}
            self.state["since"] = since
            self.state["seen"] = sorted(seen)
        summary["since"] = self.state["since"]
        return summary


class _Dead(Exception):
    pass

