import copy, json

def order(id, t, status="paid", email="ana@example.com", total=999, **extra):
    o = {"id": id, "updated_at": t, "created_at": "2026-11-19T10:00:00Z", "currency": "EUR", "total_cents": total, "status": status,
         "customer": {"first_name": "Ana", "last_name": "Silva", "email": email},
         "lines": [{"sku": "BK", "qty": 1, "unit_cents": total}]}
    o.update(extra)
    return o

class Shop:
    def __init__(self):
        self.orders = {}
    def put(self, o):
        self.orders[o["id"]] = o
    def delete(self, id, t):
        self.orders[id] = {"id": id, "updated_at": t, "deleted": True}
    def changed_orders(self, since):
        found = [copy.deepcopy(o) for o in self.orders.values() if since is None or o["updated_at"] >= since]
        return sorted(found, key=lambda o: o["updated_at"])

class Books:
    def __init__(self):
        self.invoices = {}
        self.transient = {}
        self.calls = []
    def _maybe_fail(self, key):
        if self.transient.get(key, 0) > 0:
            self.transient[key] -= 1
            raise Transient("accounting is busy")
    def create_invoice(self, invoice):
        self.calls.append("create")
        self._maybe_fail(invoice["external_ref"])
        if invoice["email"].endswith("@invalid.test"):
            raise ValueError("422 email rejected")
        new_id = f"INV-{len(self.invoices) + 1}"
        self.invoices[new_id] = dict(invoice)
        return new_id
    def update_invoice(self, invoice_id, invoice):
        self.calls.append("update")
        self._maybe_fail(invoice["external_ref"])
        self.invoices[invoice_id] = dict(invoice)
    def void_invoice(self, invoice_id):
        self.calls.append("void")
        self.invoices[invoice_id]["state"] = "void"

def setup():
    shop, books = Shop(), Books()
    return shop, books, OrderSync(shop, books, 60)

@test("a first run creates and links")
def _():
    shop, books, sync = setup()
    shop.put(order("1001", 10))
    shop.put(order("1002", 12, total=1500))
    check_eq(sync.run(), {"created": 2, "updated": 0, "voided": 0, "dead": 0, "since": 12})
    check_eq(sync.state["links"], {"1001": "INV-1", "1002": "INV-2"})
    check_eq(books.invoices["INV-2"]["amount"], "15.00")
    check_eq(books.invoices["INV-1"]["external_ref"], "shop-1001")

@test("reruns and changes")
def _():
    shop, books, sync = setup()
    shop.put(order("1001", 10))
    sync.run()
    check_eq(sync.run(), {"created": 0, "updated": 0, "voided": 0, "dead": 0, "since": 10})
    shop.put(order("1001", 11, status="refunded"))
    check_eq(sync.run()["updated"], 1)
    check_eq(books.invoices["INV-1"]["state"], "void")
    check_eq(len(books.invoices), 1)

@test("tombstones void the invoice")
def _():
    shop, books, sync = setup()
    shop.put(order("1001", 10))
    sync.run()
    shop.delete("1001", 20)
    shop.delete("9999", 20)
    check_eq(sync.run(), {"created": 0, "updated": 0, "voided": 1, "dead": 0, "since": 20})
    check_eq(books.calls, ["create", "void"])

@test("bad orders become dead letters and do not block")
def _():
    shop, books, sync = setup()
    shop.put(order("1001", 10, status="pending"))
    shop.put(order("1002", 11, email="bo@invalid.test"))
    shop.put(order("1003", 12))
    check_eq(sync.run(), {"created": 1, "updated": 0, "voided": 0, "dead": 2, "since": 12})
    check_eq(sync.state["dead"], [{"order": "1001", "reason": "mapping: unmapped status: pending"},
                                  {"order": "1002", "reason": "books: 422 email rejected"}])
    shop.put(order("1001", 13, status="paid"))
    check_eq(sync.run()["created"], 1)
    check_eq(sync.state["dead"], [{"order": "1002", "reason": "books: 422 email rejected"}])
    shop.put(order("1002", 14, email="bo@invalid.test", total=5, lines=[{"sku": "X", "qty": 1, "unit_cents": 5}]))
    check_eq(sync.run()["dead"], 1)
    check_eq(len(sync.state["dead"]), 1)

@test("temporary failures are retried")
def _():
    shop, books, sync = setup()
    books.transient["shop-1001"] = 2
    books.transient["shop-1002"] = 3
    shop.put(order("1001", 10))
    shop.put(order("1002", 11))
    summary = sync.run()
    check_eq((summary["created"], summary["dead"]), (1, 1))
    check_eq(sync.state["links"], {"1001": "INV-1"})
    check_eq(sync.state["dead"], [{"order": "1002", "reason": "books: accounting is busy"}])
    check_eq(books.calls.count("create"), 6)

@test("state survives JSON")
def _():
    shop, books, sync = setup()
    shop.put(order("1001", 10))
    shop.put(order("1002", 10, status="pending"))
    sync.run()
    saved = json.loads(json.dumps(sync.state))
    again = OrderSync(shop, books, 60, state=saved)
    check_eq(again.run(), {"created": 0, "updated": 0, "voided": 0, "dead": 0, "since": 10})
    shop.put(order("1001", 15, total=2000))
    check_eq(again.run()["updated"], 1)
    check_eq(books.invoices["INV-1"]["amount"], "20.00")
    check_eq(len(books.invoices), 1)

